 * Pure drag-reorder helpers. No DOM, no mutation of inputs.
 */

function clamp(n: number, min: number, max: number): number {
  return Math.min(Math.max(n, min), max);
}

/**
 * Move a single item from index `from` to index `to`.
 * `to` is interpreted against the original list (standard array-move
 * semantics) and clamped to valid bounds.
 * Returns a new array; never mutates `list`.
 */
export function moveItem<T>(list: readonly T[], from: number, to: number): T[] {
  if (from < 0 || from >= list.length || !Number.isInteger(from)) {
    throw new RangeError(`moveItem: source index ${from} out of bounds`);
  }
  const result = list.slice();
  const [item] = result.splice(from, 1);
  const target = clamp(to, 0, list.length - 1);
  result.splice(target, 0, item);
  return result;
}

/**
 * Move multiple items (e.g. a multi-select drag) to `to`, preserving
 * their relative order and inserting them as one contiguous block.
 *
 * `to` is an insertion index expressed against the *original* list,
 * i.e. the same value computeDropIndex would produce on the un-reordered
 * list. Indices less than `to` that are themselves being moved do not
 * push the insertion point rightward, because they travel with the block.
 *
 * Returns a new array; never mutates `list` or reads `indices` destructively.
 */
export function moveItems<T>(
  list: readonly T[],
  indices: readonly number[],
  to: number,
): T[] {
  const unique = [...new Set(indices)].sort((a, b) => a - b);
  if (unique.length === 0) return list.slice();
  for (const i of unique) {
    if (i < 0 || i >= list.length || !Number.isInteger(i)) {
      throw new RangeError(`moveItems: index ${i} out of bounds`);
    }
  }

  const moving = new Set(unique);
  // Items that stay put, in order.
  const rest: T[] = [];
  for (let i = 0; i < list.length; i++) {
    if (!moving.has(i)) rest.push(list[i]);
  }
  // Block keeps its original relative order.
  const block = unique.map((i) => list[i]);

  // Shift the insertion point left by however many moved items sat before it.
  let insertAt = to;
  for (const i of unique) {
    if (i < to) insertAt--;
    else break;
  }
  insertAt = clamp(insertAt, 0, rest.length);

  return [...rest.slice(0, insertAt), ...block, ...rest.slice(insertAt)];
}

export interface ItemRect {
  top: number;
  height: number;
}

/**
 * Compute the index a dragged item should occupy given the pointer's Y
 * coordinate and the rects of the visible items.
 *
 * Each item's vertical midpoint acts as the flip threshold: dropping
 * above an item's midpoint places the dragged item *before* it; dropping
 * at or below places it *after*. Equivalently, the result is the number
 * of midpoints strictly above the pointer.
 *
 * Returns a new-array-safe pure function of its inputs.
 */
export function computeDropIndex(
  pointerY: number,
  itemRects: readonly ItemRect[],
): number {
  let index = 0;
  for (const { top, height } of itemRects) {
    if (pointerY < top + height / 2) break;
    index++;
  }
  return index;
}
