result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/reorder/src/index.test.ts", "content": "import { describe, expect, it } from 'vitest';
import { computeDropIndex, moveItem, moveItems } from './index';

describe('moveItem', () => {
  it('moves forward', () => {
    expect(moveItem(['a', 'b', 'c', 'd'], 0, 2)).toEqual(['b', 'c', 'a', 'd']);
  });

  it('moves backward', () => {
    expect(moveItem(['a', 'b', 'c', 'd'], 3, 1)).toEqual(['a', 'd', 'b', 'c']);
  });

  it('no-op when from === to', () => {
    expect(moveItem(['a', 'b', 'c'], 1, 1)).toEqual(['a', 'b', 'c']);
  });

  it('clamps out-of-range targets to the ends', () => {
    expect(moveItem(['a', 'b', 'c'], 0, 99)).toEqual(['b', 'c', 'a']);
    expect(moveItem(['a', 'b', 'c'], 2, -5)).toEqual(['c', 'a', 'b']);
  });
});

describe('moveItems', () => {
  it('moves a contiguous multi-selection forward as a block', () => {
    expect(moveItems([0, 1, 2, 3, 4], [1, 2], 4)).toEqual([0, 3, 1, 2, 4]);
  });

  it('moves a contiguous multi-selection backward as a block', () => {
    expect(moveItems([0, 1, 2, 3, 4], [2, 3], 0)).toEqual([2, 3, 0, 1, 4]);
  });

  it('preserves relative order of non-contiguous selections', () => {
    expect(moveItems(['a', 'b', 'c', 'd', 'e'], [4, 0, 2], 5)).toEqual([
      'b',
      'd',
      'a',
      'c',
      'e',
    ]);
  });

  it('straddling: drop point between selected indices', () => {
    // Selecting b, c, e and dropping at index 3 pushes the whole block
    // ahead of d, even though c originally sat before d.
    expect(moveItems(['a', 'b', 'c', 'd', 'e'], [1, 2, 4], 3)).toEqual([
      'a',
      'b',
      'c',
      'e',
      'd',
    ]);
  });

  it('straddling: drop point inside the selection span is a stable reorder', () => {
    // Dropping at 2 with selection [1, 3]: only index 1 precedes the drop
    // point, so the block lands back where it started.
    expect(moveItems(['a', 'b', 'c', 'd'], [1, 3], 2)).toEqual([
      'a',
      'b',
      'c',
      'd',
    ]);
  });

  it('handles duplicate and unsorted indices', () => {
    expect(moveItems(['a', 'b', 'c', 'd'], [3, 1, 1], 0)).toEqual([
      'b',
      'd',
      'a',
      'c',
    ]);
  });

  it('empty selection returns a copy', () => {
    const list = ['a', 'b'];
    const result = moveItems(list, [], 0);
    expect(result).toEqual(list);
    expect(result).not.toBe(list);
  });
});

describe('computeDropIndex', () => {
  const rects = [
    { top: 0, height: 50 }, // midpoint 25
    { top: 50, height: 50 }, // midpoint 75
    { top: 100, height: 100 }, // midpoint 150
  ];

  it('drops before the first midpoint', () => {
    expect(computeDropIndex(24.9, rects)).toBe(0);
    expect(computeDropIndex(-10, rects)).toBe(0);
  });

  it('flips exactly at each midpoint', () => {
    expect(computeDropIndex(25, rects)).toBe(1);
    expect(computeDropIndex(75, rects)).toBe(2);
    expect(computeDropIndex(150, rects)).toBe(3);
  });

  it('drops after the last midpoint', () => {
    expect(computeDropIndex(150.01, rects)).toBe(3);
    expect(computeDropIndex(10_000, rects)).toBe(3);
  });

  it('returns 0 for empty rects', () => {
    expect(computeDropIndex(42, [])).toBe(0);
  });

  it('handles uneven gaps between items', () => {
    const gapped = [
      { top: 10, height: 20 }, // midpoint 20
      { top: 500, height: 10 }, // midpoint 505
    ];
    expect(computeDropIndex(19, gapped)).toBe(0);
    expect(computeDropIndex(21, gapped)).toBe(1);
    expect(computeDropIndex(600, gapped)).toBe(2);
  });
});

describe('immutability', () => {
  it('moveItem does not mutate a frozen input', () => {
    const frozen = Object.freeze(['a', 'b', 'c']) as string[];
    expect(() => moveItem(frozen, 0, 2)).not.toThrow();
    expect(moveItem(frozen, 0, 2)).toEqual(['b', 'c', 'a']);
    expect(frozen).toEqual(['a', 'b', 'c']);
  });

  it('moveItems does not mutate frozen inputs', () => {
    const frozenList = Object.freeze(['a', 'b', 'c', 'd']) as string[];
    const frozenIndices = Object.freeze([2, 0]) as number[];
    expect(() => moveItems(frozenList, frozenIndices, 3)).not.toThrow();
    expect(moveItems(frozenList, frozenIndices, 3)).toEqual([
      'b',
      'a',
      'c',
      'd',
    ]);
    expect(frozenList).toEqual(['a', 'b', 'c', 'd']);
  });

  it('computeDropIndex accepts deeply frozen rects', () => {
    const rects = Object.freeze([
      Object.freeze({ top: 0, height: 10 }),
      Object.freeze({ top: 10, height: 10 }),
    ]) as ReadonlyArray<Readonly<{ top: number; height: number }>>;
    expect(() => computeDropIndex(15, rects)).not.toThrow();
    expect(computeDropIndex(15, rects)).toBe(1);
  });
});
"})
